            seed_sql: mod1Seed,
            expected_query: "DELETE FROM movies WHERE rating < 7.5;",
            verification_query: "SELECT id, title, rating FROM movies ORDER BY id;",
            starterQuery: "SELECT * FROM movies;",
            table_names: [
                "movies"
            ]
