            seed_sql: mod1Seed,
            expected_query: "ALTER TABLE movies ADD COLUMN genre TEXT;",
            verification_query: "SELECT id, title, genre FROM movies LIMIT 3;",
            starterQuery: "-- Write ALTER TABLE here",
