                            code: "START TRANSACTION; UPDATE accounts SET balance = balance - 100 WHERE id = 4; SAVEPOINT sp1; UPDATE accounts SET balance = balance - 500 WHERE id = 4; ROLLBACK TO SAVEPOINT sp1; COMMIT;"
